// Clean Hostnames: extract nmap.org hosts from ANY response shape (ctlogs.dev rows[], crt.sh array, etc.)
const DOMAIN = 'nmap.org';
const CHUNK = 30;
const SKIP_KEYS = new Set(['url', 'self', 'href', 'links', 'error', 'message', 'status', 'statusCode', 'headers']);
const RE = /(?<![a-z0-9_*.-])(?:[a-z0-9_*-]+\.)*nmap\.org(?![a-z0-9_-]|\.[a-z0-9])/gi;
const VALID = /^[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?(\.[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?)*$/;

const found = new Set();
let rawTokens = 0, wildcards = 0, failedSources = 0, okItems = 0;
const errors = [];

function walk(v, depth) {
  if (depth > 8 || v === null || v === undefined) return;
  if (typeof v === 'string') {
    const m = v.match(RE);
    if (m) for (const t of m) {
      rawTokens++;
      const host = t.toLowerCase().replace(/\.$/, '');
      if (host.includes('*')) { wildcards++; continue; }       // drop wildcard entries
      if (!VALID.test(host)) continue;
      if (host === DOMAIN || host.endsWith('.' + DOMAIN)) found.add(host); // Set = dedupe
    }
    return;
  }
  if (Array.isArray(v)) { for (const x of v) walk(x, depth + 1); return; }
  if (typeof v === 'object') {
    for (const [k, x] of Object.entries(v)) { if (!SKIP_KEYS.has(k)) walk(x, depth + 1); }
  }
}

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.error) {
    failedSources++;
    const e = j.error;
    errors.push(String((e && (e.message || e.description)) || JSON.stringify(e)).slice(0, 120));
    continue;
  }
  okItems++;
  walk(j, 0);
}

const hosts = [...found].sort();
if (hosts.length === 0) {
  return [{ json: { hosts: [], noHosts: true,
    note: 'No subdomains retrieved from CT sources (' + failedSources + ' source error(s)' + (errors.length ? ': ' + errors[0] : '') + ')' } }];
}
const out = [];
for (let i = 0; i < hosts.length; i += CHUNK) {
  out.push({ json: { hosts: hosts.slice(i, i + CHUNK), total: hosts.length, rawTokens, wildcards, failedSources } });
}
return out;

