// Parse, Validate, Filter >=2 and Group by tag
const ALLOWED = ['admin', 'dev', 'staging', 'api', 'other'];
const ORDER = ['admin', 'dev', 'staging', 'api', 'other'];
const FORBIDDEN = ['malicious', 'compromised', 'hacked', 'cyberattack', 'under attack', 'breached', 'exploited', 'infected', 'vulnerable'];
const MAX_MSG = 3300;

const expected = [];
for (const it of $('Clean Hostnames').all()) for (const h of (it.json.hosts || [])) expected.push(h);
const expectedSet = new Set(expected);

function extract(raw) {
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string') return null;
  let s = raw.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('['), o = s.indexOf('{');
  const tryRange = (open, close) => {
    const st = s.indexOf(open), en = s.lastIndexOf(close);
    if (st === -1 || en <= st) return null;
    try { return JSON.parse(s.slice(st, en + 1)); } catch (e) { return null; }
  };
  if (o !== -1 && (a === -1 || o < a)) return tryRange('{', '}') || tryRange('[', ']');
  return tryRange('[', ']') || tryRange('{', '}');
}

function toEntries(p) {
  if (Array.isArray(p)) return p;
  if (p && typeof p === 'object') {
    for (const k of ['results', 'hosts', 'items', 'classifications', 'data']) if (Array.isArray(p[k])) return p[k];
    if (p.host || p.hostname) return [p];
  }
  return [];
}

const valid = new Map();
for (const item of $input.all()) {
  if (item.json.error) continue;
  for (const e of toEntries(extract(item.json.output ?? item.json.text))) {
    if (!e || typeof e !== 'object') continue;
    const host = String(e.host || e.hostname || '').toLowerCase().trim().replace(/\.$/, '');
    if (!expectedSet.has(host) || valid.has(host)) continue;
    const tag = String(e.tag || e.category || '').toLowerCase().trim();
    const priority = Math.round(Number(e.priority));
    if (!ALLOWED.includes(tag) || !Number.isFinite(priority) || priority < 1 || priority > 5) continue;
    let reason = String(e.reason || '').replace(/\s+/g, ' ').trim();
    if (!reason || FORBIDDEN.some(w => reason.toLowerCase().includes(w))) reason = 'Hostname pattern suggests ' + (tag === 'api' || tag === 'admin' ? 'an ' : 'a ') + tag + ' role.';
    if (reason.length > 140) reason = reason.slice(0, 137) + '...';
    valid.set(host, { host, tag, priority, reason });
  }
}

const results = [...valid.values()];
const failed = expected.filter(h => !valid.has(h));
let stats = expected.length + ' hosts scanned | ' + results.length + ' classified | ' + failed.length + ' failed validation';
if (failed.length) stats += '\nUnclassified: ' + failed.slice(0, 10).join(', ') + (failed.length > 10 ? ' ...' : '');

const sevOf = p => p >= 4 ? 'red' : p === 3 ? 'orange' : p === 2 ? 'green' : 'none';
const range = { red: 'priority 4-5', orange: 'priority 3', green: 'priority 2' };
const out = [];

for (const sev of ['red', 'orange', 'green']) {
  const list = results.filter(r => sevOf(r.priority) === sev);   // priority >= 2 filter happens here (none = P1 dropped)
  if (!list.length) continue;
  const parts = [];
  let cur = '';
  for (const tag of ORDER) {
    const g = list.filter(r => r.tag === tag).sort((a, b) => b.priority - a.priority || a.host.localeCompare(b.host));
    if (!g.length) continue;
    let head = tag.toUpperCase() + ' (' + g.length + ')';
    cur += (cur ? '\n\n' : '') + head;
    for (const r of g) {
      const line = '\n• ' + r.host + ' [P' + r.priority + '] — ' + r.reason;
      if (cur.length + line.length > MAX_MSG) { parts.push(cur); cur = tag.toUpperCase() + ' (cont.)'; }
      cur += line;
    }
  }
  if (cur) parts.push(cur);
  parts.forEach((body, i) => out.push({ json: {
    severity: sev, part: i + 1, parts: parts.length, count: list.length,
    summary: list.length + ' host(s) ' + range[sev] + ' on nmap.org', body, stats } }));
}

if (!out.length) {
  if (results.length === 0) {
    out.push({ json: { severity: 'error', emoji: '⚠️', verdict: 'AI FAILURE / check', part: 1, parts: 1, count: 0,
      summary: 'AI classification failed for all ' + expected.length + ' hosts - check Groq credential or rate limit', body: '', stats } });
  } else {
    out.push({ json: { severity: 'none', emoji: '⚪', verdict: 'CLEAR / none', part: 1, parts: 1, count: 0,
      summary: 'No hosts with priority >= 2 on nmap.org', body: '', stats } });
  }
}
return out;

